def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count recent behavior over the last 10 rounds
    recent = history[-10:]
    opp_c = sum(1 for a, b in recent if b == 'C')
    opp_d = len(recent) - opp_c
    my_c = sum(1 for a, b in recent if a == 'C')
    my_d = len(recent) - my_c

    # Last few moves
    last_my, last_opp = history[-1]
    if n >= 2:
        prev_my, prev_opp = history[-2]
    else:
        prev_my, prev_opp = ('C', 'C')

    # Detect exploit patterns: opponent defects a lot recently
    # Tit-for-tat base with forgiveness and anti-exploitation.
    if opp_d >= 7:
        # Opponent is heavily defecting; defend mostly but occasionally try C to reset
        if last_opp == 'D' and (n % 5 != 0):
            return 'D'
        if opp_d == 10:
            return 'D'
        return 'C' if rng.random() < 0.2 else 'D'

    if opp_d >= 4:
        # Generally mirror last opponent move, with slight forgiveness
        if last_opp == 'D':
            # Forgive occasionally to avoid mutual defection traps
            if opp_d >= 6 and rng.random() < 0.15:
                return 'C'
            return 'D'
        else:
            return 'C'

    # Opponent mostly cooperative
    if last_opp == 'C':
        # If we've been cooperating too, continue
        if my_c >= 7:
            return 'C'
        # If we defected last and opponent still cooperated, reward with C
        if last_my == 'D':
            return 'C'
        return 'C'
    else:
        # Opponent defected after mostly cooperating; one retaliation then forgive
        if prev_opp == 'D' and last_opp == 'D':
            # Two defections in a row against cooperative opponent: retaliate
            return 'D'
        if last_my == 'D' and last_opp == 'D':
            # Avoid endless DD; try to restart cooperation
            return 'C'
        return 'D'
